"""Capacity evidence, not an unlabeled method or source preparation result."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[2];H=R/'research/round124';rd=lambda p:json.loads(Path(p).read_text())
def main():
 assert rd(H/'SCALAR_AUDIT.json')['n']==384;agg=rd(H/'scores_attempt001/AGGREGATE_ROWS.json');summary=rd(H/'CAPACITY_SUMMARY.json');conc=rd(H/'CONCENTRATION.json');cases=rd(H/'GOOD_FAILURE_CASES_PRIVATE.json');a={r['arm']:r for r in agg if r['frame_group']=='all' and r['source']=='all_three_equal'}
 lines=['# R124 — 精确pointAdapter接口的源域GT受控能力诊断','','**本轮使用源域GT作临时逐输入干预，不是无标签TTA、不是source训练，也不产生部署checkpoint。** 不能把本表oracle数值作为方法性能。沿用已授权的source标签诊断；三个source100和R91所有原权重在每条输入后恢复，目标域、FINAL、外部专家及新原始观测均不进入本轮。','','## 为什么需要这项不同于R121的检查','','R123真实注册点InfoNCE已完成：全部786有效A/B的拟合目标下降，C对应损失也改善，正确与错配首步方向余弦约−0.71至−0.91，但选框DEV/EXP相对同信息冻结均值分别−0.1154/−0.0891个百分点。它确实使用了对应关系，却未得到任务收益。','','R121只诊断RGB GroupNorm224参数，R77诊断远大于当前的模块集合，均不能回答当前pointAdapter输出4896参数的实际能力。因此本轮固定R123接口、初始化与三步预算，仅把训练信号替换为受控的source GT最佳可用候选集合。目的不是再找一层或扫描步幅，而是检查这份实际接口在相同预算下能否改变有用的排序。','','## 固定条件与标签边界','','384条旧sourceVAL缓存，每个source128，早已用于训练验证/模型选择，不能称独立验证。相同完整文字、原A256/六层位置、点特征与RGB标定缓存。零步使用native foundation：pointAdapter.up权重/偏置和early RGB门置零，source-trained down固定。RGB late与竞争残差来自相同sourceA原准备模型，固定不随更新漂移。','','只修改Up的288×16权重与288偏置，4896参数。每步−g/||g||，半径完全沿用R123：原source整个pointAdapter范数的1%。固定三步主项；一步仅为过程记录，不按成绩选取。随机端点与对应oracle端点实际累计参数范数相同。没有回溯、源域重新训练、输出头重训或新模块。','','GT loss是最大IoU候选集合的概率质量负对数，绝对1e−8认定并列；全零IoU的输入不产生GT梯度。这个目标会泄露真实目标，因而绝不作为无标签算法或目标域选择器部署。最大IoU也不是实例身份人工真值，只是固定候选上的task-controlled supervision。','','## 工程、梯度与独立验证','','六条工程输入的原生h/U与旧source缓存逐值相同，零步Top1复现旧R121 context；实际只写4896参数并恢复source。每条工程对GT梯度做中心有限差分，全部通过。正式384条预测和临时状态封存后，CPU独立重算1920次匹配读出、实际范数、全部归一化步骤与随机端点，核对全部source缓存IoU及总体/场景/组别。','','边界需要明确：未在CPU上重复整个decoder的所有反向传播。梯度方向验证来自六条工程有限差分，全量CPU检查从保存梯度重构步进及最终独立head读出。报告不把有限的检查写成全量独立decoder反传。首次路径预检捕获历史wildcard导入覆盖H/B常量，在任何模型调用之前已停止并修复，失败代码/日志/原锁保留，不改变诊断配方。','','## 全体总体与各source','','| 范围 | 方法 | mIoU% | Acc25% | Acc50% |','|---|---|---:|---:|---:|']
 for x in agg:
  if x['frame_group']=='all':lines.append(f"| {x['source']} | {x['arm']} | {x['mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} |")
 gain=a['oracle3']['mIoU_percent']-a['zero']['mIoU_percent'];lines+=['','## 本轮能够支持的判断','',f'相同三步接口的source-GT干预相对自身零步为 **{gain:+.6f} 个百分点**。这属于受控源域能力，不是TTA增益。',('因此，不能再笼统地把R123失败归因于“这个接口完全改不动选框”。已测预算下存在grounding有用的参数方向；但源域GT的可用方向不等于在目标域能无标签地识别这些方向。R123已实测的注册点目标没有可靠选中有益方向，不能靠source oracle成绩宣布修复。' if gain>0 else '该预算下source-GT的最终选框也没有总体增益，说明实际接口/预算限制仍是竞争解释。这不是所有pointAdapter编辑的数学上界，也不能据此否定其它监督或充分任务训练。'),'','本轮不把GT更新、梯度或最佳步数带回目标域。R123固定配方继续停止；不重新包装为一个已成功的三模态TTA方法。无标签信号仍须在相同信息直接使用、错配、随机及未拟合观测上独立证明任务增量。','','## 所有改善、损伤和集中度','','```json',json.dumps(conc,indent=2),'```','','全部IoU变化案例均保留在匿名逐例表。换query不直接等同于换物体；未进行私有原图身份复核的实例类别保持UNKNOWN。源域GT过拟合的good case只说明受控监督可以改变决策，不是算法正确发现目标的证据。','','## 优化、范围与审计','','```json',json.dumps(summary,indent=2),json.dumps(rd(H/'NATIVE_AUDIT.json'),indent=2),json.dumps(rd(H/'SCALAR_AUDIT.json'),indent=2),'```','','三个source各自结果与所有场景、既有帧组均完整公开；不选择表现最好的source或删负例。旧sourceVAL有82个Waymo场景、Drone2个、Quad3个，场景重复和已曝光限制不因384条规模而消失。共享研究seconds不代表单方法新鲜端到端成本。公开排除原文、原图、原点云、框坐标、query索引、特征、参数状态和梯度。']
 (H/'REPORT.md').write_text('\n'.join(lines)+'\n');print({'source_GT_oracle3_gain_pp':gain,'NOT_TTA':True,'no_deployed_weights':True},flush=True)
if __name__=='__main__':main()
